// Builds one self-contained file per Edge Function in supabase/functions-dashboard/<name>.ts, for
// pasting into the Supabase dashboard editor (which cannot import ../_shared across functions).
// The sources of truth stay in supabase/functions/*; do not edit the generated files by hand.
import { mkdirSync, readFileSync, writeFileSync } from 'node:fs';
import path from 'node:path';
import { fileURLToPath } from 'node:url';

const root = path.join(path.dirname(fileURLToPath(import.meta.url)), '..', 'supabase');
const src = path.join(root, 'functions');
const out = path.join(root, 'functions-dashboard');
mkdirSync(out, { recursive: true });

const FUNCTIONS = ['login', 'create-submission-draft', 'confirm-submission', 'cleanup-drafts', 'request-new-key', 'admin-manage', 'contest-export'];
const RELATIVE_IMPORT = /^import\s[^;]*?from\s+'(\.[^']+)';?\s*$/gm;

function collect(file, seen = new Set(), order = []) {
  if (seen.has(file)) return order;
  seen.add(file);
  const text = readFileSync(file, 'utf8');
  for (const m of text.matchAll(RELATIVE_IMPORT)) collect(path.resolve(path.dirname(file), m[1]), seen, order);
  order.push(file);
  return order;
}

for (const fn of FUNCTIONS) {
  const files = collect(path.join(src, fn, 'index.ts'));
  const npmImports = new Set();
  const parts = files.map((f) => {
    let text = readFileSync(f, 'utf8');
    text = text.replace(RELATIVE_IMPORT, '');
    text = text.replace(/^import\s[^;]*?from\s+'(npm:[^']+)';?\s*$/gm, (line) => { npmImports.add(line.trim()); return ''; });
    text = text.replace(/^export (?=(async function|function|const|interface|type|class)\b)/gm, '');
    return `// ---- ${path.relative(src, f)}\n${text.trim()}\n`;
  });
  const header = `// Edge Function "${fn}" as a single file for the Supabase dashboard editor.
// Generated by scripts/build-dashboard-functions.mjs from supabase/functions/. Do not edit by hand.
// In the dashboard: Edge Functions -> Deploy a new function -> Via Editor -> name it "${fn}",
// paste this whole file, Deploy, then switch "Verify JWT" OFF for it (this function checks the caller itself).
`;
  writeFileSync(path.join(out, `${fn}.ts`), `${header}\n${[...npmImports].join('\n')}\n\n${parts.join('\n')}`);
  console.log(`${fn}.ts  (${files.length} modules inlined)`);
}
